// CalcSums sets each of the decimal or integer fields to its total over the records matching
// the current filters (CalcSums)
func (t *ResourcePriceChange) CalcSums(fieldNames ...string) error {
	tableName := fmt.Sprintf("%s$%s", t.company, ResourcePriceChangeTableName)
	where, args := t.buildWhereClause()
	for _, name := range fieldNames {
		var column string
		switch strings.ToLower(name) {
		case "current_unit_price":
			column = "current_unit_price"
		case "new_unit_price":
			column = "new_unit_price"
		default:
			return fmt.Errorf("CalcSums: %s is not a decimal or integer field of Resource_Price_Change", name)
		}
		query := t.convertPlaceholders(fmt.Sprintf(`SELECT CAST(COALESCE(SUM(%s), 0) AS TEXT) FROM "%s" WHERE %s`, column, tableName, where), len(args))
		var total string
		if err := t.exec().QueryRow(query, args...).Scan(&total); err != nil {
			return fmt.Errorf("CalcSums Resource_Price_Change.%s: %w", column, err)
		}
		switch column {
		case "current_unit_price":
			d, err := types.NewDecimalFromString(total)
			if err != nil {
				return fmt.Errorf("CalcSums Resource_Price_Change.%s: %w", column, err)
			}
			t.Current_unit_price = d
		case "new_unit_price":
			d, err := types.NewDecimalFromString(total)
			if err != nil {
				return fmt.Errorf("CalcSums Resource_Price_Change.%s: %w", column, err)
			}
			t.New_unit_price = d
		}
	}
	return nil
}

